import { useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
};

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() + days);
  return base;
};

const presets: { id: string; label: string; getDate: () => Date }[] = [
  { id: 'today', label: 'Сегодня', getDate: () => shiftDays(0) },
  { id: 'yesterday', label: 'Вчера', getDate: () => shiftDays(-1) },
  { id: 'week-ago', label: 'Неделя назад', getDate: () => shiftDays(-7) },
];

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : internalDate;

  const select = (next: Date | null) => {
    if (value === undefined) setInternalDate(next);
    onChange?.(next);
  };

  const activePreset = presets.find(
    (preset) => selected != null && startOfDay(selected).getTime() === preset.getDate().getTime(),
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', fontFamily: 'var(--jx-font-sans)' }}>
      <div role="group" aria-label="Быстрый выбор даты отчёта" style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => {
          const isActive = activePreset?.id === preset.id;
          return (
            <JxButton
              key={preset.id}
              size="sm"
              variant={isActive ? 'primary' : 'outline'}
              aria-pressed={isActive}
              onClick={() => select(preset.getDate())}
            >
              {preset.label}
            </JxButton>
          );
        })}
      </div>

      <JxCalendar locale={locale} value={selected} onValueChange={select} />

      <p style={{ margin: 0, color: 'var(--jx-text-2)', fontSize: '13px' }}>
        {selected
          ? `Дата отчёта: ${selected.toLocaleDateString(locale, {
              day: 'numeric',
              month: 'long',
              year: 'numeric',
            })}`
          : 'Дата не выбрана — выберите день в календаре или нажмите быстрый вариант выше.'}
      </p>
    </div>
  );
}

